const express = require('express');
const bcrypt = require('bcrypt');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { Pool } = require('pg');
const Joi = require('joi');

const app = express();
app.use(express.json());

// FIX 1: Helmet ile güvenlik header'ları
app.use(helmet());

// FIX 2: CORS whitelist
const allowedOrigins = [
  'https://myapp.com',
  'https://admin.myapp.com'
];
if (process.env.NODE_ENV === 'development') {
  allowedOrigins.push('http://localhost:3000');
}
app.use(cors({
  origin: function(origin, callback) {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS not allowed'));
    }
  },
  credentials: true
}));

// FIX 3: Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Çok fazla giriş denemesi, lütfen bekleyin' },
  skipSuccessfulRequests: true
});

app.use('/api/', apiLimiter);
app.use('/api/auth/login', loginLimiter);

const db = new Pool({ connectionString: process.env.DATABASE_URL });

// Input validation schemas
const registerSchema = Joi.object({
  name: Joi.string().min(2).max(50).required(),
  email: Joi.string().email().max(255).required(),
  password: Joi.string().min(8).max(128)
    .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .required()
});

// FIX 4+5+6: Parameterized query, bcrypt, input validation
app.post('/api/auth/register', async (req, res) => {
  try {
    // Input validation
    const { error, value } = registerSchema.validate(req.body);
    if (error) {
      return res.status(400).json({
        error: 'Validation hatası',
        details: error.details.map(d => d.message)
      });
    }

    const { name, email, password } = value;

    // Check duplicate email (parameterized)
    const existing = await db.query('SELECT id FROM users WHERE email = $1', [email]);
    if (existing.rows.length > 0) {
      return res.status(409).json({ error: 'Bu email zaten kayıtlı' });
    }

    // bcrypt ile hash (MD5 yerine)
    const passwordHash = await bcrypt.hash(password, 12);

    // Parameterized query (SQL injection koruması)
    const query = 'INSERT INTO users (name, email, password_hash) VALUES ($1, $2, $3) RETURNING id, name, email, created_at';
    const result = await db.query(query, [name, email, passwordHash]);

    // Password hash response'da YOK (RETURNING'de belirtmedik)
    res.status(201).json(result.rows[0]);
  } catch (error) {
    // Stack trace GİZLİ
    console.error('Register error:', error);
    res.status(500).json({ error: 'Sunucu hatası' });
  }
});

// FIX 7+8+9: Login güvenliği
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email ve şifre gerekli' });
    }

    // Parameterized query
    const result = await db.query('SELECT * FROM users WHERE email = $1', [email]);
    const user = result.rows[0];

    // Generic hata mesajı (user enumeration koruması)
    if (!user || !(await bcrypt.compare(password, user.password_hash))) {
      return res.status(401).json({ error: 'Geçersiz email veya şifre' });
    }

    // Güvenli cookie
    res.cookie('session', user.id, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 24 * 60 * 60 * 1000
    });

    res.json({ message: 'Giriş başarılı' });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Sunucu hatası' });
  }
});

// FIX 10: User endpoint güvenliği
app.get('/api/users/:id', async (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Geçersiz kullanıcı ID' });
    }

    // Parameterized query + password hash hariç
    const result = await db.query(
      'SELECT id, name, email, created_at FROM users WHERE id = $1',
      [userId]
    );

    if (!result.rows[0]) {
      return res.status(404).json({ error: 'Kullanıcı bulunamadı' });
    }

    res.json(result.rows[0]);
  } catch (error) {
    console.error('User fetch error:', error);
    res.status(500).json({ error: 'Sunucu hatası' });
  }
});

// FIX 11: Search endpoint güvenliği
app.get('/api/search', async (req, res) => {
  try {
    const { q } = req.query;
    if (!q || typeof q !== 'string') {
      return res.status(400).json({ error: 'Arama terimi gerekli' });
    }

    // Parameterized LIKE query
    const result = await db.query(
      'SELECT id, name, description, price FROM products WHERE name ILIKE $1 LIMIT 50',
      [`%${q}%`]
    );

    res.json(result.rows);
  } catch (error) {
    console.error('Search error:', error);
    res.status(500).json({ error: 'Sunucu hatası' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Sunucu hatası'
      : err.message
  });
});

app.listen(3000);
